// Category A (overlay) — behavior borrowed from react-aria-components, look owned in src.
// Compound component: Select (wrapper) + SelectItem (option). The overlay is a Popover (portal).
// Subcomponent naming convention: flat <Parent><ParentSubpart> named export (no dot notation).
// (Contract: docs/rules/component-contract.md · naming: docs/rules/naming-convention.md)
import {
  Select as AriaSelect,
  SelectValue,
  Label,
  Button,
  ListBox,
  ListBoxItem,
  Text,
  FieldError,
} from "react-aria-components";
import { PopoverContent } from "./Popover";
import type {
  SelectProps as AriaSelectProps,
  ListBoxItemProps,
  ValidationResult,
} from "react-aria-components";
import { Check, ChevronDown } from "./icons";
import type { ReactNode, Ref } from "react";
import { roleSize, type ControlSize } from "./controlSize";
import "./Select.css";

type SelectSize = ControlSize;
type SelectVariant = "outline" | "filled";

type SelectSelectionMode = "single" | "multiple";

/** `selectionMode="multiple"` lets the reader pick several options; the trigger then lists them and
 *  each selected option carries a check (React Aria's own multiple Select). `value` and `onChange`
 *  take a key array in that mode. */
export interface SelectProps<M extends SelectSelectionMode = "single">
  extends Omit<AriaSelectProps<object, M>, "className" | "children"> {
  /**
   * Visual variant. `outline` draws the bordered trigger; `filled` draws a borderless trigger on a
   * neutral fill, for a select that sits in a toolbar or a dense table header. Focus and invalid still show their border colour in both.
   *
   * @default "outline"
   */
  variant?: SelectVariant;
  /**
   * Size axis (trigger height/padding/font).
   *
   * @default "medium"
   */
  size?: SelectSize;
  /** Label layout: above the trigger, or inside before the value.
   * @default "outside"
   */
  labelPlacement?: "outside" | "inside";
  /** Field label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Supporting description. */
  description?: string;
  /** Validation-failure message (shown in the isInvalid state). */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Text shown when nothing is selected. */
  placeholder?: string;
  /**
   * SelectItem list. When **static**, pass `<SelectItem>` nodes; when **dynamic**, pass a function
   * that renders each item paired with `items` — RAC ListBox's dynamic-collection contract
   * (Calendar's month/year picker uses this `items` + function form).
   */
  children?: ReactNode | ((item: object) => ReactNode);
  /**
   * Dynamic collection source. When passed, each item is rendered by the `children` function
   * (omit for static nodes). Passes RAC ListBox's `items` straight through.
   */
  items?: Iterable<object>;
  /** Content shown when the list is empty. */
  renderEmptyState?: () => ReactNode;
  /** Additional class (optional). sd-select is always preserved. */
  className?: string;
  /** Forwarded to the underlying select DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function Select<M extends SelectSelectionMode = "single">({
  variant = "outline",
  size = "medium",
  labelPlacement = "outside",
  label,
  contextualHelp,
  description,
  errorMessage,
  placeholder,
  children,
  items,
  renderEmptyState,
  className,
  ref,
  ...props
}: SelectProps<M>) {
  return (
    <AriaSelect
      {...props}
      ref={ref}
      placeholder={placeholder}
      className={className ? `sd-select ${className}` : "sd-select"}
    >
      {({ isInvalid, isDisabled }) => {
        /* RAC only puts data-invalid on the wrapper, not the trigger button —
           relay it so the trigger border reflects the invalid state. */
        const trigger = (
          <Button
            data-label-placement={labelPlacement}
            data-size={size}
            data-variant={variant}
            data-invalid={isInvalid || undefined}
            className="sd-select__trigger"
          >
            {labelPlacement === "inside" && label && (
              <Label elementType="span" data-label-placement="inside" className={`sd-select__label sd-type-label-${roleSize(size)}`}>
                {label}
              </Label>
            )}
            <SelectValue data-label-placement={labelPlacement} className={labelPlacement === "inside" ? `sd-select__value sd-type-body-${roleSize(size)}-emphasized` : "sd-select__value"} />
            <span aria-hidden="true" data-size={size} className="sd-select__icon">
              <ChevronDown size="1em" />
            </span>
          </Button>
        );
        return (
        <>
          {labelPlacement === "outside" && (contextualHelp ? (
            <div className="sd-select__label-group">
              {label && (
                <Label data-disabled={isDisabled || undefined} className={`sd-select__label sd-type-label-${roleSize(size)}`}>
                  {label}
                </Label>
              )}
              {contextualHelp}
            </div>
          ) : (
            label && (
              <Label
                data-disabled={isDisabled || undefined}
                className={`sd-select__label sd-type-label-${roleSize(size)}`}
              >
                {label}
              </Label>
            )
          ))}
          {/* With the label inside, the help trigger sits beside the trigger on its row: a button
              cannot nest in the trigger, and alone above it the help would name nothing. */}
          {labelPlacement === "inside" && contextualHelp ? (
            <div className="sd-select__label-group">
              {trigger}
              {contextualHelp}
            </div>
          ) : (
            trigger
          )}
          {description && (
            <Text
              slot="description"
              className={`sd-select__description sd-type-caption-${roleSize(size)}`}
            >
              {description}
            </Text>
          )}
          <FieldError className={`sd-select__error sd-type-caption-${roleSize(size)}`}>
            {errorMessage}
          </FieldError>
          {/* The shared PopoverContent owns the overlay surface (surface small + elevation high).
              The reason for small: this surface contains a **selection list**, and list surfaces
              must use the same tier as Menu — if the same kind of content does not appear with the
              same spacing · rounding, the two dropdowns read as different objects. medium
              (padding 16 / R28) was merely the result of inheriting the default, and for a list
              where each item has its own spacing, the outer surface was also wide, making it doubly
              sparse. One surface tier drives padding and radius together (§ surface pairing).
              ListBox manages role=listbox · roving-tabindex itself → omit Dialog wrapping (noDialog). */}
          <PopoverContent noDialog size="small" matchTriggerWidth>
            <ListBox
              className="sd-select__listbox"
              items={items}
              renderEmptyState={
                renderEmptyState ??
                (() => (
                  <div className="sd-select__empty sd-type-caption-medium">
                    No options available.
                  </div>
                ))
              }
            >
              {children}
            </ListBox>
          </PopoverContent>
        </>
        );
      }}
    </AriaSelect>
  );
}

export interface SelectItemProps extends Omit<ListBoxItemProps, "className"> {
  /** Optional leading icon, shown before the label. */
  icon?: ReactNode;
  /** Trailing content pinned to the option's end, before the multiple-selection check: a Badge or
   *  a short note ("Default", a count). It is read as part of the option's name; type-to-select
   *  matches `textValue` alone, which string `children` still provide. */
  trailing?: ReactNode;
  /** Additional class. sd-select__item is always retained. */
  className?: string;
  /** Passed to the underlying option DOM element. */
  ref?: Ref<HTMLDivElement>;
}

export function SelectItem({
  icon,
  trailing,
  className,
  children,
  textValue,
  ...props
}: SelectItemProps) {
  return (
    <ListBoxItem
      {...props}
      // Children render via a function (icon + label), so RAC can't auto-derive textValue
      // and type-to-select would break. Re-derive from string children (matches
      // ListBoxItem / MenuItem); pass an explicit `textValue` when children aren't plain text.
      textValue={textValue || (typeof children === "string" ? children : undefined)}
      className={
        className
          ? `sd-select__item sd-type-body-medium ${className}`
          : "sd-select__item sd-type-body-medium"
      }
    >
      {(renderProps) => (
        <>
          {icon && (
            <span className="sd-select__item-icon" aria-hidden="true">
              {icon}
            </span>
          )}
          {typeof children === "function" ? children(renderProps) : children}
          {/* The end of the row holds the trailing content and the check in one run, so one auto
              margin pins both: two would split the free space and float the first mid-row. */}
          {(trailing != null || (renderProps.selectionMode === "multiple" && renderProps.isSelected)) && (
            <span className="sd-select__item-end">
              {trailing != null && <span className="sd-select__item-trailing">{trailing}</span>}
              {/* Several options can be on at once, so each says so itself; one selected option is
                  already named by the trigger. Decorative: React Aria exposes the selected state. */}
              {renderProps.selectionMode === "multiple" && renderProps.isSelected && (
                <span className="sd-select__item-check" aria-hidden="true">
                  <Check size="1em" />
                </span>
              )}
            </span>
          )}
        </>
      )}
    </ListBoxItem>
  );
}

/* Select.css — .sd-select (+ BEM 서브파트)
   분류 A(오버레이): 동작 빌림, 룩 소유. 파트 = trigger·value·icon·popover·listbox·item.
   규칙: sd- 프리픽스 / 평평한 단일 클래스 / 상태는 react-aria data-* / Cmp 토큰 참조.
   (focus-ring 색만 Sys 직참조 — 전역 불변 carve-out, TextField와 동일) */
.sd-select {
  display: flex;
  flex-direction: column;
  gap: var(--sd-select-gap);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-select__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-select-label-group-gap);
}

.sd-select__label {
  padding-inline: var(--sd-select-text-padding-inline);
  color: var(--sd-select-label-foreground);
}
.sd-select__label[data-disabled] {
  opacity: var(--sd-state-disabled);
}

/* trigger */
.sd-select__trigger {
  --sd-select-trigger-radius-current: var(--sd-select-trigger-radius-medium);
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sd-select-trigger-gap);
  width: 100%;
  position: relative;
  /* its own stacking context, so the content's z-index above a state layer stays inside it */
  isolation: isolate;
  background: var(--sd-select-trigger-background);
  color: var(--sd-select-trigger-foreground);
  border: var(--sd-select-trigger-border-width) solid var(--sd-select-trigger-border);
  border-radius: var(--sd-select-trigger-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  cursor: pointer;
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
  outline: none;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-select-trigger-state-hover-current: var(--sd-state-hover);
  --sd-select-trigger-state-pressed-current: var(--sd-state-pressed);
}
.sd-select__trigger[data-size="x-small"] {
  --sd-select-trigger-radius-current: var(--sd-select-trigger-radius-x-small);
  font-size: var(--sd-select-trigger-font-size-x-small);
  height: var(--sd-select-trigger-height-x-small);
  padding-inline: var(--sd-select-trigger-padding-inline-x-small);
}
.sd-select__trigger[data-size="small"] {
  --sd-select-trigger-radius-current: var(--sd-select-trigger-radius-small);
  font-size: var(--sd-select-trigger-font-size-small);
  height: var(--sd-select-trigger-height-small);
  padding-inline: var(--sd-select-trigger-padding-inline-small);
}
.sd-select__trigger[data-size="medium"] {
  --sd-select-trigger-radius-current: var(--sd-select-trigger-radius-medium);
  font-size: var(--sd-select-trigger-font-size-medium);
  height: var(--sd-select-trigger-height-medium);
  padding-inline: var(--sd-select-trigger-padding-inline-medium);
}
.sd-select__trigger[data-size="large"] {
  --sd-select-trigger-radius-current: var(--sd-select-trigger-radius-large);
  font-size: var(--sd-select-trigger-font-size-large);
  height: var(--sd-select-trigger-height-large);
  padding-inline: var(--sd-select-trigger-padding-inline-large);
}
.sd-select__trigger[data-size="x-large"] {
  --sd-select-trigger-radius-current: var(--sd-select-trigger-radius-x-large);
  font-size: var(--sd-select-trigger-font-size-x-large);
  height: var(--sd-select-trigger-height-x-large);
  padding-inline: var(--sd-select-trigger-padding-inline-x-large);
}
.sd-select__trigger[data-hovered] {
  border-color: var(--sd-select-trigger-border-hover);
}
.sd-select__trigger[data-focused] {
  border-color: var(--sd-select-trigger-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-select__trigger[data-invalid] {
  border-color: var(--sd-select-trigger-border-invalid);
}
.sd-select__trigger[data-invalid][data-focused] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-select-trigger-border-invalid) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
/* filled — a borderless trigger on the neutral fill. The border keeps its width, transparent at
   rest, so focus and invalid can still colour it; their filled rules below restate the colour
   because this rest rule outranks the plain state rules above. Hover and press are the state layer,
   since there is no edge to darken (ADR-0009); the value and icon sit above it at z-index 1, contained
   by the trigger's `isolation`. */
.sd-select__trigger[data-variant="filled"] {
  background: var(--sd-select-trigger-background-filled);
  border-color: var(--sd-select-trigger-border-filled);
  --sd-select-trigger-state-hover-current: var(--sd-state-hover-neutral-subtle);
  --sd-select-trigger-state-pressed-current: var(--sd-state-pressed-neutral-subtle);
}
.sd-select__trigger[data-variant="filled"]::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-select__trigger[data-variant="filled"][data-hovered]::after {
  background: var(--sd-select-trigger-state-hover-current);
}
.sd-select__trigger[data-variant="filled"][data-pressed]::after {
  background: var(--sd-select-trigger-state-pressed-current);
}
.sd-select__trigger[data-variant="filled"][data-focused] {
  border-color: var(--sd-select-trigger-border-focus);
}
.sd-select__trigger[data-variant="filled"][data-invalid] {
  border-color: var(--sd-select-trigger-border-invalid);
}
.sd-select__trigger[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* value / icon */
.sd-select__value {
  position: relative;
  z-index: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  /* The chosen item's icon renders here too, on a line rather than in the item's flex row, so the
     item's gap does not reach it. A block keeps the ellipsis; the gap is relayed to the icon. */
  --sd-select-item-icon-gap-current: var(--sd-select-item-gap);
  /* The same holds for a trailing badge: on a line its `auto` margin computes to 0 and it sat flush
     on the value, so the trigger relays the gap a badge takes after the text it annotates. */
  --sd-select-item-end-gap-current: var(--sd-select-item-gap);
}
.sd-select__value[data-placeholder] {
  color: var(--sd-select-placeholder-foreground);
}
.sd-select__icon {
  position: relative;
  z-index: 1;
  flex-shrink: 0;
  /* A flex box, not a line box: as a block the glyph sits on a text baseline with the descent below
     it, 2px above the trigger's middle. */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--sd-select-icon-foreground);
}
/* trigger chevron on the icon scale per size (12/16/20), like every other field icon. */
.sd-select__icon[data-size="x-small"] {
  font-size: var(--sd-select-icon-size-x-small);
}
.sd-select__icon[data-size="small"] {
  font-size: var(--sd-select-icon-size-small);
}
.sd-select__icon[data-size="medium"] {
  font-size: var(--sd-select-icon-size-medium);
}
.sd-select__icon[data-size="large"] {
  font-size: var(--sd-select-icon-size-large);
}
.sd-select__icon[data-size="x-large"] {
  font-size: var(--sd-select-icon-size-x-large);
}

/* description / error */
.sd-select__description {
  padding-inline: var(--sd-select-text-padding-inline);
  color: var(--sd-select-description-foreground);
}
.sd-select__error {
  padding-inline: var(--sd-select-text-padding-inline);
  color: var(--sd-select-error-foreground);
}

/* popover (overlay) — the floating surface (bg·border·radius·shadow·padding·scroll·motion·
   trigger-width via `matchTriggerWidth`) is owned by the shared PopoverContent (Select.tsx:
   <PopoverContent noDialog>). */

/* listbox */
.sd-select__listbox {
  outline: none;
  display: flex;
  flex-direction: column;
}

.sd-select__empty {
  padding: var(--sd-select-empty-padding-block) var(--sd-select-empty-padding-inline);
  color: var(--sd-select-empty-foreground);
  text-align: center;
}

/* item */
.sd-select__item {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: var(--sd-select-item-gap);
  padding: var(--sd-select-item-padding-block) var(--sd-select-item-padding-inline);
  border-radius: var(--sd-select-item-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  color: var(--sd-select-item-foreground);
  cursor: pointer;
  outline: none;
  /* The hover wash over this part: the surface wash, or over a fill the one named for that fill,
     which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-select-item-state-hover-current: var(--sd-state-hover);
}
/* Interaction state-layer overlay: composites over selected bg (ADR-0009). */
.sd-select__item::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-select__item[data-hovered]::after,
.sd-select__item[data-focused]::after {
  background: var(--sd-select-item-state-hover-current);
}
.sd-select__item[data-selected] {
  background: var(--sd-select-item-background-selected);
  --sd-select-item-state-hover-current: var(--sd-state-hover-selected);
}
.sd-select__item[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* The option's end: its trailing content, then the check a selected option carries when several
   can be chosen, pinned together by one auto margin. */
.sd-select__item-end {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  gap: var(--sd-select-item-gap);
  /* `auto` in an option's flex row, pinning the end to it; the closed trigger's line sets the gap
     (above), and `middle` centres the run on that line rather than on its baseline. */
  margin-inline-start: var(--sd-select-item-end-gap-current, auto);
  vertical-align: middle;
}
.sd-select__item-trailing {
  display: inline-flex;
  align-items: center;
}
.sd-select__item-check {
  display: inline-flex;
  align-items: center;
  font-size: var(--sd-select-item-icon-size);
}

.sd-select__item-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 var(--sd-select-item-icon-size);
  width: var(--sd-select-item-icon-size);
  height: var(--sd-select-item-icon-size);
  font-size: var(--sd-select-item-icon-size);
  vertical-align: middle;
  margin-inline-end: var(--sd-select-item-icon-gap-current, 0);
}

/* Placement is independent of the trigger's visual variant. RAC Label retains its naming slot. */
.sd-select__trigger[data-label-placement="inside"] {
  justify-content: flex-start;
  --sd-select-inside-label-foreground-current: var(--sd-select-inside-label-foreground);
}
.sd-select__trigger[data-label-placement="inside"][data-hovered],
.sd-select__trigger[data-label-placement="inside"][data-pressed] {
  --sd-select-inside-label-foreground-current: var(--sd-select-trigger-foreground);
}
.sd-select__label[data-label-placement="inside"] {
  position: relative;
  z-index: 1;
  flex: 0 1 auto;
  min-width: 0;
  padding: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--sd-select-inside-label-foreground-current);
}
.sd-select__value[data-label-placement="inside"] {
  flex: 1 1 auto;
  min-width: 0;
  text-align: start;
}
